// Is this package path, in any case, one the stock game ships?
inline bool IsStockPackage(std::string_view path) {
    uint64_t h = 0xcbf29ce484222325ull;
    for (char ch : path) {
        const unsigned char c = static_cast<unsigned char>(ch);
        h = (h ^ (c >= 'A' && c <= 'Z' ? c + 32u : c)) * 0x100000001b3ull;
    }
    return std::binary_search(std::begin(kStockPackageHashes), std::end(kStockPackageHashes), h);
}

